function ok(node) {
  if (node === null) return true
  if (node.left !== null && node.left.val > node.val) return false
  if (node.right !== null && node.right.val === node.val) return false
  if (node.right !== null && node.val > node.right.val) return false
  return ok(node.left) && ok(node.right)
}

function insert(node, x) {
  if (node === null) return { val: x, left: null, right: null }
  if (x > node.val) insert(node.right, x)
  else insert(node.left, x)
  return node
}
